//
// The text of native/binding.js: the entry that hands the loader this package's names,
// stamps the loaded artifact and re-exports every napi export by name. The loading logic
// is in native/loader/.

const exportLine = (name) => `module.exports.${name} = nativeBinding.${name}`

export function renderBinding({ binaryName, packageName, version, idents }) {
  return `/* eslint-disable */
// @ts-nocheck
/* generated by scripts/write-binding.mjs; the loading logic is in ./loader */

const { loadBinding, stampBindingTarget } = require('./loader/index.js')

const { binding: nativeBinding, target: loadedBindingTarget } = loadBinding({
  require,
  binaryName: '${binaryName}',
  packageName: '${packageName}',
  version: '${version}',
})

// The assignment keeps the marker a statically visible CommonJS export: \`cjs-module-lexer\`
// is Node's CJS -> ESM named export detection, it cannot see a bare call, and the later
// \`module.exports = nativeBinding\` does not undo the detection. It lands on this module's
// own \`module.exports\`, still the original object, before the alias replaces it; what a
// consumer reads is whatever \`stampBindingTarget\` put on \`nativeBinding\`.
module.exports.__napiBindingTarget = stampBindingTarget(nativeBinding, loadedBindingTarget)
module.exports = nativeBinding
${idents.map(exportLine).join('\n')}
`
}
